/* ==UserStyle==
@name Hyperpipe Catppuccin
@namespace github.com/catppuccin/userstyles/styles/hyperpipe
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/hyperpipe
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/hyperpipe/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Ahyperpipe
@description Soothing pastel theme for Hyperpipe
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("hyperpipe.surge.sh") {
  body {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  body[data-theme^="light"] {
    #catppuccin(@lightFlavor);
  }

  body[data-theme^="dark"],
  body[data-theme^="black"],
  body[data-theme^="dracula"],
  body[data-theme^="nord"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --color-foreground: @accent !important;
    --color-background: @base !important;
    --color-background-soft: @surface0 !important;
    --color-background-mute: @surface1 !important;
    --color-border: @surface0 !important;
    --color-border-hover: @overlay0 !important;
    --color-shadow: @crust !important;
    --color-blur: fade(@mantle, 45%) !important;
    --color-gradient: linear-gradient(
      45deg,
      @accent,
      fade(@accent, 45%)
    );
    --color-scrollbar: @accent !important;
    --color-heading: @text !important;
    --color-text: @text !important;
  }
}

